                errors = errors + 1;
            end
            @(posedge clk);
        end

        // 3. Asynchronous/Synchronous reset mid-count test
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 4'b0000) begin
            $display("Error: Mid-count reset failed. Expected 0, got %b", q);
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        #1;
        if (q !== 4'b0001) begin
            $display("Error: Post-reset counting failed. Expected 1, got %b", q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
